    "jsHint": "JS debe devolver un objeto como valor de retorno de setup del componente Vue. Usa ctx.api.get('/me') para llamar a la API del backend. Después de guardar, visita la página del portal para ver el resultado real.",
    "ctxApiRefBody": "ctx.ref(val)              — crear una variable reactiva\nctx.computed(fn)          — crear una propiedad computada\nctx.watch(src, cb)        — observar cambios\nctx.onMounted(fn)         — al montar el componente\nctx.onUnmounted(fn)       — al desmontar el componente\n\nctx.data.client           — información de la cuenta del usuario (reactiva)\nctx.data.token            — token actual (reactivo)\nctx.data.isDark           — modo oscuro (reactivo)\n\nctx.api.get(path, query)  — solicitud GET\nctx.api.post(path, body)  — solicitud POST\nctx.api.put(path, body)   — solicitud PUT\nctx.api.delete(path)      — solicitud DELETE\n\nctx.formatBytes(bytes)    — formatear el tamaño de un archivo\nctx.formatDate(date)      — formatear una fecha\nctx.copyText(text)        — copiar al portapapeles\nctx.elMessage             — mensaje de Element Plus\nctx.config                — configuración del portal (PORTAL_CONFIG)\nctx.moduleId              — ID del módulo actual\nctx.moduleTitle           — título del módulo actual",
